-- CPF R6 approval policy immutability/audit extension
-- vendor=oracle; logicalDatabase=admDB
BEGIN
  EXECUTE IMMEDIATE q'[CREATE TABLE adm_approval_policy_history (
    POLICY_HISTORY_ID NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    POLICY_CODE VARCHAR2(80 CHAR) NOT NULL,
    POLICY_VERSION NUMBER(10) NOT NULL,
    CHANGE_TYPE VARCHAR2(30 CHAR) NOT NULL,
    CHANGE_REASON VARCHAR2(500 CHAR) NOT NULL,
    BEFORE_HASH CHAR(64 CHAR),
    AFTER_HASH CHAR(64 CHAR) NOT NULL,
    OPERATOR_ID VARCHAR2(50 CHAR) NOT NULL,
    CREATED_AT TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT pk_adm_approval_policy_history PRIMARY KEY (POLICY_HISTORY_ID),
    CONSTRAINT fk_adm_approval_policy_history_policy FOREIGN KEY (POLICY_CODE, POLICY_VERSION)
      REFERENCES adm_approval_policy (POLICY_CODE, POLICY_VERSION),
    CONSTRAINT ck_adm_approval_policy_history_hash CHECK
      ((BEFORE_HASH IS NULL OR LENGTH(BEFORE_HASH)=64) AND LENGTH(AFTER_HASH)=64)
  )]';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -955 THEN RAISE; END IF;
END;
/
BEGIN
  EXECUTE IMMEDIATE 'CREATE INDEX ix_adm_approval_policy_history_policy ON adm_approval_policy_history (POLICY_CODE, POLICY_VERSION, POLICY_HISTORY_ID)';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -955 THEN RAISE; END IF;
END;
/
COMMENT ON TABLE adm_approval_policy_history IS 'Immutable approval policy version audit history';
